const body = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const timeMin = body.time_min || body.timeMin || new Date().toISOString();
const rawMax = body.time_max || body.timeMax || null;
const timeMax = rawMax || new Date(new Date(timeMin).getTime() + 7*24*3600*1000).toISOString();
const parseCalendarIds = (value) => {
  const rawValues = Array.isArray(value) ? value : [value];
  const seen = new Set();
  const ids = [];
  for (const rawValue of rawValues) {
    const parts = String(rawValue || '')
      .split(/[\n,;]+/)
      .map((entry) => entry.trim())
      .filter(Boolean);
    for (const part of parts) {
      if (seen.has(part)) continue;
      seen.add(part);
      ids.push(part);
    }
  }
  return ids;
};
const defaultCalendarIds = [
  body.calendar_id || body.calendarId || 'raul.ruiz.diaz.bcn@gmail.com',
  body.holiday_calendar_id || body.holidayCalendarId || 'es.spain#holiday@group.v.calendar.google.com',
];
const calendarIds = parseCalendarIds(body.calendar_ids || body.calendarIds || defaultCalendarIds);
return calendarIds.map((calendarId) => ({ json: { timeMin, timeMax, calendarId } }));

const events = $input.all()
  .map(item => item.json)
  .filter(ev => ev && ev.id && (ev.start?.dateTime || ev.start?.date));
const normalize = (ev) => ({
  google_calendar_event_id: ev.id,
  calendar_id: ev.organizer?.email || ev.creator?.email || null,
  summary: ev.summary || '',
  inicio_en: ev.start?.dateTime || ev.start?.date || null,
  fin_en: ev.end?.dateTime || ev.end?.date || null,
  description: ev.description || null,
  status: ev.status || 'confirmed',
  transparency: ev.transparency || null,
  all_day: Boolean(ev.start?.date && !ev.start?.dateTime)
});
const seen = new Set();
const busyEvents = [];
for (const ev of events) {
  const normalized = normalize(ev);
  if (!normalized.inicio_en) continue;
  if ((normalized.status || '').toLowerCase() === 'cancelled') continue;
  if ((normalized.transparency || '').toLowerCase() === 'transparent' && !normalized.all_day) continue;
  const dedupeKey = `${normalized.google_calendar_event_id}::${normalized.calendar_id || ''}`;
  if (seen.has(dedupeKey)) continue;
  seen.add(dedupeKey);
  busyEvents.push(normalized);
}
const fisioEvents = busyEvents
  .filter(ev => (ev.summary || '').toLowerCase().includes('cita fisioterapia'));
return [{ json: { events: fisioEvents, busy_events: busyEvents, total: fisioEvents.length, busy_total: busyEvents.length } }];

